// ─── File: src/test/java/com/bank/queues/BlockingQueuesComparisonTest.java ───
package com.bank.queues;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class BlockingQueuesComparisonTest {

    // ═══ ArrayBlockingQueue: fixed, fair option ═══
    @Test
    void arrayBlockingQueue_fixedCapacity() throws InterruptedException {
        BlockingQueue<String> q = new ArrayBlockingQueue<>(3);
        q.put("A"); q.put("B"); q.put("C");
        assertThat(q.offer("D")).isFalse();  // full! Returns false!
        assertThat(q.take()).isEqualTo("A"); // FIFO!
    }

    // ═══ LinkedBlockingQueue: two locks, concurrent put+take ═══
    @Test
    void linkedBlockingQueue_concurrentPutTake() throws InterruptedException {
        BlockingQueue<String> q = new LinkedBlockingQueue<>(1000);
        CountDownLatch done = new CountDownLatch(2);

        // Producer and consumer can run CONCURRENTLY (two locks!)
        new Thread(() -> { try { for (int i = 0; i < 100; i++) q.put("item-" + i); } catch (InterruptedException e) {} done.countDown(); }).start();
        new Thread(() -> { try { for (int i = 0; i < 100; i++) q.take(); } catch (InterruptedException e) {} done.countDown(); }).start();

        done.await(5, TimeUnit.SECONDS);
        assertThat(q).isEmpty();  // all consumed!
    }

    // ═══ PriorityBlockingQueue: ordered by priority ═══
    @Test
    void priorityBlockingQueue_highestFirst() throws InterruptedException {
        PriorityBlockingQueue<Integer> q = new PriorityBlockingQueue<>();
        q.put(50000); q.put(10000000); q.put(100); q.put(5000000);

        assertThat(q.take()).isEqualTo(100);       // smallest first (min-heap)!
        assertThat(q.take()).isEqualTo(50000);
        assertThat(q.take()).isEqualTo(5000000);
        assertThat(q.take()).isEqualTo(10000000);
        // For highest-first: use Comparator.reverseOrder()!
    }

    // ═══ SynchronousQueue: zero capacity, direct handoff ═══
    @Test
    void synchronousQueue_directHandoff() throws InterruptedException {
        SynchronousQueue<String> q = new SynchronousQueue<>();
        assertThat(q.offer("item")).isFalse();  // no consumer waiting → rejected!

        CountDownLatch done = new CountDownLatch(1);
        new Thread(() -> {
            try { assertThat(q.take()).isEqualTo("direct!"); }  // blocks until put!
            catch (InterruptedException e) {}
            done.countDown();
        }).start();

        Thread.sleep(100);
        q.put("direct!");  // handoff! Consumer takes immediately!
        done.await(5, TimeUnit.SECONDS);
    }

    // ═══ DelayQueue: released after delay ═══
    @Test
    void delayQueue_releasedAfterDelay() throws InterruptedException {
        DelayQueue<Delayed> q = new DelayQueue<>();
        long start = System.currentTimeMillis();

        q.put(new Delayed() {
            final long readyTime = System.currentTimeMillis() + 500;  // 500ms delay!
            public long getDelay(TimeUnit unit) {
                return unit.convert(readyTime - System.currentTimeMillis(), TimeUnit.MILLISECONDS);
            }
            public int compareTo(Delayed o) { return Long.compare(getDelay(TimeUnit.MILLISECONDS), o.getDelay(TimeUnit.MILLISECONDS)); }
        });

        Delayed item = q.take();  // blocks until 500ms delay expires!
        long elapsed = System.currentTimeMillis() - start;
        assertThat(elapsed).isGreaterThanOrEqualTo(400);  // waited ~500ms!
    }
}
